"""Verbatim source anchors and proposed LaTeX; does not edit locked manuscripts."""
from engineering_common import *

def run():
 target=OUT/'05_MANUSCRIPT_AMENDMENTS/EXACT_LATEX_REPLACEMENTS.json'
 if target.exists():return
 source=consume(LOCK/'GATE3_MANUSCRIPT/main.tex');text=source.read_text(encoding='utf-8');lines=text.splitlines();edits=[]
 def replacement(id,starts,new,reason):
  hits=[(i+1,line) for i,line in enumerate(lines) if line.startswith(starts)];assert len(hits)==1
  line,old=hits[0];assert text.count(old)==1
  edits.append(dict(id=id,source=str(source),source_sha256=sha(source),line=line,operation='replace_exact_paragraph',old_latex=old,new_latex=new,reason=reason))
 replacement('physical_scope','The unit MW',r'''The unit MW$\cdot$h$\cdot$row-state denotes the sum of thermal exceedances over monitored rows, states and time. Contingency multiplicity contributes repeatedly by definition; $S$ is neither unserved energy, probability-weighted risk nor simultaneous overloaded power. The fixed transaction matrix specifies balanced bus-injection changes without generator-specific allocation, headroom, reserve or ramp constraints. Unit commitment, storage intertemporal physics and AC constraints are not optimized. Thermal slacks ensure algebraic feasibility despite physical overload.''','State the physical and objective scope before the first numerical table.')
 replacement('premium_AC_coverage','Here $\lambda_e',r'''Here $\lambda_e^{AC}$ is loading percent divided by 100. A policy-difference deadband of $10^{-4}$ separates ties from material orderings. This normalized comparison is not the annual unnormalized objective $S$. The original 2,106-record registry excludes $C_q$, $U_{1.25}$ and their exposure-controlled witnesses; a separately versioned matched evaluation of those trajectories is reported below.''','Keep the historical registry description while removing the implication that no new premium replay exists.')
 replacement('new_engineering_evidence','The AC registry excludes',r'''A new participant-level constant-power-factor evaluation sets $C_Q=C_P^{\rm final}$ as a declared common-embedding assumption, while preserving the historical two-map model as a separate sensitivity. At the original 18 hours, three states and three power factors, rolling M2, $U_{1.25}$, $C_q$ and retrospective $x^{\rm EC}$ give 648 records per mapping. All converge; under the common map, thermal passes are 84, 66, 78 and 66 of 162, respectively, with a maximum loading of 278.40\%. All pass the declared voltage and simple reactive-bound checks. Mapping changes do not alter paired ordering or feasibility classifications at the stated tolerances. These selected fixed-injection checks do not establish annual security. The balancing key has no identified generator-specific allocation; a fleet-only aggregate diagnostic fails in part because some balancing buses contain no device in the inventoried native generator/interchange fleet. Other load or renewable allocations remain outside that conditional test.''','Distinguish new common-map results, historical sensitivity and conditional headroom limits; preserve adverse thermal findings.')
 replacement('conclusion','These results concern synthetic',r'''These results concern synthetic transport nominations, an hourly deterministic DC evaluator with fixed counter-injections, and penalized overloads. Matched premium AC checks retain substantial thermal violations under both the historical and declared common participant mappings. The system-level conclusion is that debit definitions change feasible operating choices and customer exposure associated with network relief. The annual numerical separation remains instance-specific and applies to the original DC accounting model. Deployment additionally requires physically feasible balancing, validated network aggregation and nonanticipative scheduling from authenticated information.''','Remove the obsolete no-premium-replay statement without extending annual certificates to a new model.')
 # Optional main-paper insertions, with exact anchors. Keep full tables in the report.
 anchor=[(i+1,line) for i,line in enumerate(lines) if line.startswith('The AC registry contains')];assert len(anchor)==1
 edits.append(dict(id='new_physical_diagnostics',source=str(source),source_sha256=sha(source),line=anchor[0][0],operation='optional_insert_before_exact_paragraph',old_latex=anchor[0][1],new_latex=r'''We additionally evaluate $V_t=\max_{c,r}[|f_{rt}^c|-F_r^c]_+$ and the hours with $V_t>1$ MW, where 1 MW is a reporting convention. For 2029--2031, $C_q$ has 7,101, 6,280 and 6,245 such hours, compared with 7,235, 6,503 and 6,470 for $U_{1.25}$. The retrospective exposure control has 8,057, 8,117 and 8,153 hours despite its lower integrated residual than U. Thus improvements in $S$ need not reduce peak loading or overload duration.''',reason='Optional compact main-paper result; detailed 21-object tables remain outside the main manuscript.'))
 edits.append(dict(id='AC_adverse_year_detail',source=str(source),source_sha256=sha(source),line=anchor[0][0],operation='technical_report_detail',old_latex='',new_latex=r'''Under the common map, the selected-case sums of $J^{AC}$ for $(C_q,U_{1.25})$ are $(24.105012,24.076207)$ in 2029, $(18.552862,22.968986)$ in 2030 and $(7.915394,7.915394)$ in 2031. The 2029 selected AC score does not share the direction of the full-year DC comparison; 2031 is tied in this selected sample. These deterministic selected-case sums are not annual or probability-weighted risks.''',reason='Make the adverse 2029 AC finding explicit; not a claim of yearlong AC dominance or ranking.'))
 jsout(target,dict(status='PROPOSED_NOT_APPLIED',authority=str(source),authority_sha256=sha(source),page_count_after_integration='NOT_CHECKED; retain compact main text and technical-report detail',edits=edits))
 csvout(OUT/'05_MANUSCRIPT_AMENDMENTS/MANUSCRIPT_SOURCE_ANCHORS.csv',pd.DataFrame([{k:v for k,v in e.items() if k not in ('old_latex','new_latex')} for e in edits]))
 tex=['% Exact source-grounded replacements. NOT applied to locked source.','% Canonical old/new strings and operations are in EXACT_LATEX_REPLACEMENTS.json.']
 for e in edits:tex.extend(['',f'% {e["id"]}: original main.tex line {e["line"]}; {e["operation"]}',e['new_latex']])
 atomic(OUT/'05_MANUSCRIPT_AMENDMENTS/EXACT_PROPOSED_REPLACEMENTS.tex','\n'.join(tex)+'\n')
 canonical=OUT/'05_MANUSCRIPT_AMENDMENTS/PROPOSED_MANUSCRIPT_CHANGES.tex'
 if canonical.exists():
  saved=OUT/'07_QC_AND_INTEGRITY/RENDER_V1/PROPOSED_MANUSCRIPT_CHANGES_GENERIC.tex';saved.parent.mkdir(parents=True,exist_ok=True)
  if saved.exists():raise RuntimeError('Generic amendment draft already preserved; inspect partial authoring stage')
  canonical.rename(saved)
 atomic(canonical,'\n'.join(tex)+'\n% Retain main.tex:327, which already states the deterministic-information and prospective-measurability limitation.\n% No abstract numerical expansion is required.\n')
 print('Verified',len(edits),'exact source anchors; locked manuscript unchanged')

if __name__=='__main__':run()
